using System.Text.Json;using HealthTracker.Api.Contracts;using HealthTracker.Api.Data;using HealthTracker.Api.Models;using Microsoft.EntityFrameworkCore;namespace HealthTracker.Api.Services;public interface IDoseService{Task<List<DoseResponse>> Get(Guid userId,DateOnly date,Guid? patientId);Task<DoseResponse> Take(Guid userId,Guid id);Task<DoseResponse> Skip(Guid userId,Guid id,string reason);Task<DoseResponse> Reschedule(Guid userId,Guid id,DateOnly date);Task<DoseResponse> Undo(Guid userId,Guid id);}public class DoseService(AppDbContext db):IDoseService{public async Task<List<DoseResponse>> Get(Guid uid,DateOnly date,Guid? patientId){var ids=await db.FamilyMembers.Where(x=>x.UserId==uid&&x.Status=="approved").Join(db.FamilyMembers,a=>a.FamilyId,b=>b.FamilyId,(a,b)=>b.UserId).Distinct().ToListAsync();if(!ids.Contains(uid))ids.Add(uid);if(patientId.HasValue){var requested=await db.Patients.FindAsync(patientId.Value);if(requested is null||!ids.Contains(requested.UserId))throw new UnauthorizedAccessException("You do not have access to this patient.");}var p=await db.Patients.SingleAsync(x=>x.Id==(patientId??Guid.Empty)||x.UserId==uid);if(patientId.HasValue&&!ids.Contains(p.UserId))throw new UnauthorizedAccessException("You do not have access to this patient.");var meds=await db.Medicines.Where(x=>x.PatientId==p.Id).ToListAsync();var result=new List<DoseResponse>();foreach(var m in meds)if(Occurs(m,date))foreach(var time in JsonSerializer.Deserialize<List<string>>(m.TimesJson)??[]){var e=await db.DoseEvents.SingleOrDefaultAsync(x=>x.PatientId==p.Id&&x.MedicineId==m.Id&&x.Date==date&&x.Time==time);if(e==null){e=new DoseEvent{PatientId=p.Id,MedicineId=m.Id,Date=date,Time=time};db.DoseEvents.Add(e);await db.SaveChangesAsync();}result.Add(Map(e,m));}return result.OrderBy(x=>x.Time).ToList();}static bool Occurs(Medicine m,DateOnly d){if(d<m.StartDate)return false;var diff=d.DayNumber-m.StartDate.DayNumber;if(m.DurationType!="ongoing"){var n=m.DurationUnit=="weeks"?m.DurationValue*7:m.DurationUnit=="months"?m.DurationValue*30:m.DurationValue;if(diff>=n)return false;}return m.FrequencyPattern switch{"daily"=>true,"everyOtherDay"=>diff%2==0,"specificDays"=>(JsonSerializer.Deserialize<List<string>>(m.SpecificDaysJson)??[]).Contains(d.DayOfWeek.ToString()[..3]),"recurringCycle"=>m.CycleUnit=="weeks"?diff%(m.CycleEvery*7)==0:m.CycleUnit=="months"?d.Day==m.StartDate.Day:diff%m.CycleEvery==0,_=>false};}static DoseResponse Map(DoseEvent e,Medicine m)=>new(e.Id,m.Id,m.Name,m.Strength,m.Form,m.Condition,e.Time,m.Liquid,m.WithFood,e.Status,e.TakenAt,e.SkipReason,e.RescheduleTo?.ToString("yyyy-MM-dd"));async Task<(DoseEvent e,Medicine m)> Event(Guid uid,Guid id){var p=await db.Patients.SingleAsync(x=>x.UserId==uid);var e=await db.DoseEvents.SingleAsync(x=>x.Id==id&&x.PatientId==p.Id);var m=await db.Medicines.SingleAsync(x=>x.Id==e.MedicineId);return(e,m);}public async Task<DoseResponse> Take(Guid u,Guid id){var x=await Event(u,id);x.e.Status="taken";x.e.TakenAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync();return Map(x.e,x.m);}public async Task<DoseResponse> Skip(Guid u,Guid id,string reason){var x=await Event(u,id);x.e.Status="skipped";x.e.SkipReason=reason;await db.SaveChangesAsync();return Map(x.e,x.m);}public async Task<DoseResponse> Reschedule(Guid u,Guid id,DateOnly d){var x=await Event(u,id);x.e.Status="rescheduled";x.e.RescheduleTo=d;await db.SaveChangesAsync();return Map(x.e,x.m);}public async Task<DoseResponse> Undo(Guid u,Guid id){var x=await Event(u,id);x.e.Status="pending";x.e.TakenAt=null;x.e.SkipReason=null;x.e.RescheduleTo=null;await db.SaveChangesAsync();return Map(x.e,x.m);}}